int fd = open("data.bin", O_RDWR);
char buffer[100];
read(fd, buffer, 100);          /* offset moves from 0 to 100 */
lseek(fd, 500, SEEK_SET);       /* offset jumps directly to 500 */
char payload[50];
write(fd, payload, 50);         /* offset moves from 500 to 550 */
close(fd);                      /* reference count drops to 0 */

